package com.wizzadrds.theworldremembers.voice; import org.junit.jupiter.api.Test; import java.nio.file.*; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*; class LocalVoiceRuntimeTest{@Test void runtimeUsesBoundedScheduler(){SpeechToTextAdapter stt=p->"hello";TextToSpeechAdapter tts=(text,profile,out)->out;var rt=new LocalVoiceRuntime(stt,tts,new VoiceScheduler(1));var id=UUID.randomUUID();assertTrue(rt.queue(id,"hello",VoicePriority.DIRECT,1));assertEquals("hello",assertDoesNotThrow(()->rt.transcribe(Path.of("ignored"))));var job=rt.next();assertNotNull(job);assertEquals(id,job.npcId());assertDoesNotThrow(()->rt.synthesize(job,new VoiceProfile("es","local",VoiceTemperament.CALM,0,0,50),Path.of("out.wav")));rt.finish(id);}}
